Here's the diff for someone who wants to send it in as a PR. It's literally a one memcpy less, so the chances of it getting accepted are minimal. That's the reason I'm not doing it. Still sending it here if someone in the future wants to try it or is doing a redesign/rewrite of PacketPeerUDP.

```diff
Author: NoNormalDev <no123normal@gmail.com>
Date:   Sun Jul 5 23:14:35 2026 +0200

    Optimize bound PacketPeerUDP.get_packet()

diff --git a/core/io/packet_peer_udp.cpp b/core/io/packet_peer_udp.cpp
index 86076044d1..7932b571ae 100644
--- a/core/io/packet_peer_udp.cpp
+++ b/core/io/packet_peer_udp.cpp
@@ -98,13 +98,12 @@ int PacketPeerUDP::get_available_packet_count() const {
 }

 Error PacketPeerUDP::get_packet(const uint8_t **r_buffer, int &r_buffer_size) {
-       Error err = _poll();
+       uint32_t size;
+
+       Error err = _read_rb_packet_header(size);
        if (err != OK) {
                return err;
        }
-       if (queue_count == 0) {
-               return ERR_UNAVAILABLE;
-       }

        /* Bogus GCC warning here:
         * In member function 'int RingBuffer<T>::read(T*, int, bool) [with T = unsigned char]',
@@ -117,12 +116,6 @@ Error PacketPeerUDP::get_packet(const uint8_t **r_buffer, int &r_buffer_size) {
        GODOT_GCC_WARNING_PUSH
        GODOT_GCC_PRAGMA(GCC diagnostic warning "-Wstringop-overflow=0") // Can't "ignore" this for some reason.

-       uint32_t size = 0;
-       uint8_t ipv6[16] = {};
-       rb.read(ipv6, 16, true);
-       packet_ip.set_ipv6(ipv6);
-       rb.read((uint8_t *)&packet_port, 4, true);
-       rb.read((uint8_t *)&size, 4, true);
        rb.read(packet_buffer, size, true);
        --queue_count;
        *r_buffer = packet_buffer;
@@ -133,6 +126,42 @@ Error PacketPeerUDP::get_packet(const uint8_t **r_buffer, int &r_buffer_size) {
        return OK;
 }

+Error PacketPeerUDP::get_packet_buffer(Vector<uint8_t> &r_buffer) {
+       uint32_t size;
+
+       Error err = _read_rb_packet_header(size);
+       if (err != OK) {
+               return err;
+       }
+
+       r_buffer.resize(size);
+       rb.read(r_buffer.ptrw(), size, true);
+
+       --queue_count;
+
+       return OK;
+}
+
+Error PacketPeerUDP::_read_rb_packet_header(uint32_t &r_size) {
+       Error err = _poll();
+       if (err != OK) {
+               return err;
+       }
+       if (queue_count == 0) {
+               return ERR_UNAVAILABLE;
+       }
+
+       uint8_t ipv6[16] = {};
+       rb.read(ipv6, 16, true);
+       packet_ip.set_ipv6(ipv6);
+
+       rb.read((uint8_t *)&packet_port, 4, true);
+
+       rb.read((uint8_t *)&r_size, 4, true);
+
+       return OK;
+}
+
 Error PacketPeerUDP::put_packet(const uint8_t *p_buffer, int p_buffer_size) {
        ERR_FAIL_COND_V(_sock.is_null(), ERR_UNAVAILABLE);
        ERR_FAIL_COND_V(!peer_addr.is_valid(), ERR_UNCONFIGURED);
diff --git a/core/io/packet_peer_udp.h b/core/io/packet_peer_udp.h
index ef005b0854..9f04204292 100644
--- a/core/io/packet_peer_udp.h
+++ b/core/io/packet_peer_udp.h
@@ -66,6 +66,8 @@ protected:
        Error _set_dest_address(const String &p_address, int p_port);
        Error _poll();

+       Error _read_rb_packet_header(uint32_t &r_size);
+
 public:
        void set_blocking_mode(bool p_enable);

@@ -87,6 +89,7 @@ public:

        Error put_packet(const uint8_t *p_buffer, int p_buffer_size) override;
        Error get_packet(const uint8_t **r_buffer, int &r_buffer_size) override;
+       Error get_packet_buffer(Vector<uint8_t> &r_buffer) override;
        int get_available_packet_count() const override;
        int get_max_packet_size() const override;
        void set_broadcast_enabled(bool p_enabled);
```
